+				const repo = `${owner}/${match[2]}`;
+				if (seenRepos.has(repo)) {
+					continue;
+				}
+
+				seenRepos.add(repo);
+				const entry = entryMap.get(owner);
+				if (entry) {
+					yield { entry, repo };
+					matchedOwners.add(owner);
+				}
+			}
+		}
+
+		// Entries with no matching are queried without repo context
